let rawJson = $input.first().json;

// Función Aplanadora: Extrae absolutamente TODO el texto de cualquier parte del objeto que devuelva la IA
function extractAllText(obj) {
    let res = "";
    if (typeof obj === 'string') return obj + " \n ";
    if (Array.isArray(obj)) {
        for (let item of obj) res += extractAllText(item);
    } else if (typeof obj === 'object' && obj !== null) {
        for (let key in obj) res += extractAllText(obj[key]);
    }
    return res;
}

let allText = extractAllText(rawJson);

// Limpiamos los bloques markdown
allText = allText.replace(/```json/g, '').replace(/```/g, '');

let aiResponse = {};

// Extraemos todo lo que haya entre la primera { y la última }
const firstBrace = allText.indexOf('{');
const lastBrace = allText.lastIndexOf('}');

if (firstBrace !== -1 && lastBrace !== -1) {
    let cleanJsonStr = allText.substring(firstBrace, lastBrace + 1);
    try {
        aiResponse = JSON.parse(cleanJsonStr);
    } catch (e) {
        aiResponse = { error: "Fallo el parseo: " + e.message, raw: cleanJsonStr };
    }
} else {
    aiResponse = { error: "No se encontraron llaves en el texto", raw: allText };
}

const webhookData = $('Webhook (Recibe CV)').first().json.body || {};

const profileData = {
  // Usamos el nombre y email extraídos de la IA como prioridad, sino recurrimos al Webhook
  full_name: aiResponse.full_name || webhookData.full_name || "Sin Nombre",
  email: aiResponse.email || webhookData.email || "",
  expected_salary_cop: webhookData.expected_salary_cop || 0,
  location_city: aiResponse.location_city || aiResponse.Ciudad || webhookData.location_city || "",
  raw_cv_url: webhookData.cv_url || "",
  parsed_cv_data: {
    skills: aiResponse.skills || [],
    experience_years: aiResponse.experience_years || 0,
    education_level: aiResponse.education_level || "NO_ESPECIFICADO",
    debug_info: aiResponse.error || "OK"
  }
};

// Devolver un arreglo con un solo elemento fuerza a n8n a descartar los items extra
return [ { json: profileData } ];
